const root = $json || {};
const body = root.body && typeof root.body === "object" ? root.body : root;
const query = root.query && typeof root.query === "object" ? root.query : {};
const params = root.params && typeof root.params === "object" ? root.params : {};

const rawUrl =
  body.hubspotUrl ??
  query.hubspotUrl ??
  params.hubspotUrl ??
  "";

const rawMode =
  body.mode ??
  query.mode ??
  params.mode ??
  "strategy";

const hubspotUrl = String(rawUrl || "").trim();
let mode = String(rawMode || "strategy").trim().toLowerCase();

if (!["summary", "full", "strategy"].includes(mode)) {
  mode = "strategy";
}

let companyId = null;

if (hubspotUrl) {
  const match = hubspotUrl.match(/\/record\/0-2\/(\d+)/);
  if (match) {
    companyId = match[1];
  }
}

if (!companyId && hubspotUrl) {
  const matches = hubspotUrl.match(/\d{6,}/g);
  if (matches && matches.length > 0) {
    companyId = matches[matches.length - 1];
  }
}

if (!companyId) {
  throw new Error("Company ID not found. Provide a valid HubSpot company URL.");
}

return [{
  json: {
    companyId,
    hubspotUrl,
    mode
  }
}];

const companyNode = $node["HubSpot_Get_Company"].json || {};
const extract = $node["Code_Extract_CompanyId"].json || {};
const contactsRes = $node["HTTP_Get_Company_Contacts"].json || {};
const dealsRes = $node["HTTP_Get_Company_Deals"].json || {};

const company = companyNode.properties || companyNode;
const mode = extract.mode || "strategy";

const contacts = Array.isArray(contactsRes.results) ? contactsRes.results : [];
const deals = Array.isArray(dealsRes.results) ? dealsRes.results : [];

const context = `
COMPANY
Name: ${company.name || ""}
Domain: ${company.domain || ""}
Website: ${company.website || ""}
Industry: ${company.industry || ""}
Country: ${company.country || ""}
City: ${company.city || ""}
Description: ${company.description || ""}
Lead status: ${company.hs_lead_status || ""}

ASSOCIATED CONTACTS
Count: ${contacts.length}

ASSOCIATED DEALS
Count: ${deals.length}
`;

let aiPrompt = "";

if (mode === "summary") {
  aiPrompt = `
You are a senior B2G education strategist working for Magrid.

Produce a SHORT account analysis.

Return only:
1. Executive Summary
2. Main Opportunity
3. Main Risk
4. Recommended Next Step

Rules:
- Keep it concise
- Formal and practical tone
- No invented facts

Context:
${context}
`;
} else if (mode === "full") {
  aiPrompt = `
You are a senior B2G education strategist working for Magrid.

Analyse the following organisation and provide:

1. Executive Summary
2. Institutional Interpretation
3. Stakeholder Hypothesis
4. Signals of Readiness
5. Risks
6. Recommended Approach
7. Next Actions

Rules:
- Be practical and concrete
- No invented facts
- Use an institutional tone

Context:
${context}
`;
} else {
  aiPrompt = `
You are a senior B2G education strategist working for Magrid.

Analyse the following organisation and provide a strategic account reading.

Return:
1. Executive Summary
2. Institutional / Political Reading
3. Stakeholder Hypothesis
4. Buying Readiness Signals
5. Risks and Frictions
6. Strategic Engagement Approach
7. Recommended Next Introductions
8. Immediate Next Actions

Rules:
- Formal and strategic tone
- No invented facts
- Adapt to ministries, NGOs, school groups, distributors when relevant

Context:
${context}
`;
}

return [{
  json: {
    company_context: context,
    ai_prompt: aiPrompt,
    mode,
    record_type: "company"
  }
}];
